def test_succeeds_on_first_try():
    @retry(3)
    def always_ok():
        return 'ok'
    assert always_ok() == 'ok', 'a function that never raises must just return its result'

def test_retries_until_success():
    attempts = []

    @retry(3)
    def flaky():
        attempts.append(1)
        if len(attempts) < 2:
            raise ValueError('not yet')
        return 'recovered'

    assert flaky() == 'recovered', 'retry must retry after a ValueError and return the eventual success'
    assert len(attempts) == 2, 'the function must have been called exactly twice before succeeding'

def test_raises_after_exhausting_attempts():
    @retry(2)
    def always_fails():
        raise ValueError('nope')

    try:
        always_fails()
        assert False, 'retry must let the exception propagate once every attempt is exhausted'
    except ValueError:
        pass

